/* BERTH.A RC230 — Kids · Raposa Neblina + Corujinha Lunar
   Correções: Raposa sem cortes/rebarbas; Corujinha realmente carregada; 5 acessórios × 3 cores.
   Assets embutidos para eliminar 404/cache de GitHub Pages.
*/
(function(){
'use strict';
const BUILD='RC230';
const PALS=['nevoa','coral','misto'];
const PREFIX='bertha.kids.accessory.variant.';
const IDS={
  'mist_mist_v1_fox_head_0':['fox','head'],
  'mist_mist_v1_fox_neck_1':['fox','neck'],
  'mist_mist_v1_fox_eyes_2':['fox','eyes'],
  'mist_mist_v1_fox_back_3':['fox','back'],
  'mist_mist_v1_fox_special_4':['fox','special'],
  'mist_mist_v1_owl_head_0':['owl','head'],
  'mist_mist_v1_owl_neck_1':['owl','neck'],
  'mist_mist_v1_owl_eyes_2':['owl','eyes'],
  'mist_mist_v1_owl_back_3':['owl','back'],
  'mist_mist_v1_owl_special_4':['owl','special']
};
const NAMES={
  'mist_mist_v1_fox_head_0':'Gorro Aurora',
  'mist_mist_v1_fox_neck_1':'Lenço Estelar',
  'mist_mist_v1_fox_eyes_2':'Óculos da Raposa',
  'mist_mist_v1_fox_back_3':'Mochila Cauda Estelar',
  'mist_mist_v1_fox_special_4':'Amuleto Raposa Celeste',
  'mist_mist_v1_owl_head_0':'Chapéu Pena Lunar',
  'mist_mist_v1_owl_neck_1':'Gravata Lua-Sábia',
  'mist_mist_v1_owl_eyes_2':'Óculos de Leitura Lunar',
  'mist_mist_v1_owl_back_3':'Bolsa-Livro Celeste',
  'mist_mist_v1_owl_special_4':'Medalhão Pena Oráculo'
};
const ASSETS={
    'fox-head-nevoa':'data:image/png;base64,',
    'fox-head-coral':'data:image/png;base64,',
    'fox-head-misto':'data:image/png;base64,',
    'fox-neck-nevoa':'data:image/png;base64,',
    'fox-neck-coral':'data:image/png;base64,',
    'fox-neck-misto':'data:image/png;base64,',
    'fox-eyes-nevoa':'data:image/png;base64,',
    'fox-eyes-coral':'data:image/png;base64,',
    'fox-eyes-misto':'data:image/png;base64,',
    'fox-back-nevoa':'data:image/png;base64,',
    'fox-back-coral':'data:image/png;base64,',
    'fox-back-misto':'data:image/png;base64,',
    'fox-special-nevoa':'data:image/png;base64,',
    'fox-special-coral':'data:image/png;base64,',
    'fox-special-misto':'data:image/png;base64,',
    'owl-head-nevoa':'data:image/png;base64,',
    'owl-head-coral':'data:image/png;base64,',
    'owl-head-misto':'data:image/png;base64,',
    'owl-neck-nevoa':'data:image/png;base64,',
    'owl-neck-coral':'data:image/png;base64,',
    'owl-neck-misto':'data:image/png;base64,',
    'owl-eyes-nevoa':'data:image/png;base64,',
    'owl-eyes-coral':'data:image/png;base64,',
    'owl-eyes-misto':'data:image/png;base64,',
    'owl-back-nevoa':'data:image/png;base64,',
    'owl-back-coral':'data:image/png;base64,',
    'owl-back-misto':'data:image/png;base64,',
    'owl-special-nevoa':'data:image/png;base64,',
    'owl-special-coral':'data:image/png;base64,',
    'owl-special-misto':'data:image/png;base64,'
};
const store=()=>window.berthaHmlStorage||window.localStorage;
function selectedKid(){const s=document.querySelector('#r152KidSel');if(s&&s.value)return String(s.value);if(window.__rc209Member!=null)return String(window.__rc209Member);return 'default';}
function variantFor(aid){const n=Number(store().getItem(PREFIX+selectedKid()+'.'+aid));return Number.isFinite(n)?Math.max(0,Math.min(2,n)):0;}
function srcFor(aid){const rec=IDS[aid];if(!rec)return '';return ASSETS[rec[0]+'-'+rec[1]+'-'+PALS[variantFor(aid)]]||'';}
function stamp(){
  document.documentElement.dataset.berthaBuild=BUILD;
  document.documentElement.dataset.berthaIndex=BUILD;
  document.title='BERTH.A · Homologação '+BUILD;
  const idx=document.getElementById('rc157IndexBadge');if(idx)idx.textContent='INDEX · '+BUILD;
  document.querySelectorAll('body *').forEach(el=>{if(el.children.length===0&&/^HML\s*·\s*RC\d+/i.test((el.textContent||'').trim()))el.textContent='HML · '+BUILD;});
}
function patch(root=document){
  root.querySelectorAll('.rc209-acc-proxy[data-acc]').forEach(proxy=>{
    const aid=proxy.getAttribute('data-acc');if(!IDS[aid])return;
    const [collection]=IDS[aid];
    proxy.classList.remove('rc224-fox-asset','rc225-owl-asset');
    proxy.classList.add('rc230-kids-asset','rc230-'+collection+'-asset');
    let im=proxy.querySelector('img');if(!im){proxy.replaceChildren();im=document.createElement('img');im.alt='';im.loading='eager';im.decoding='async';proxy.appendChild(im);}
    const src=srcFor(aid);if(src&&im.src!==src)im.setAttribute('src',src);
    im.setAttribute('data-rc230',aid);
    const card=proxy.closest('.r197-acc');if(card){const s=card.querySelector('strong');if(s&&NAMES[aid])s.textContent=NAMES[aid];}
  });
  stamp();
}
const style=document.createElement('style');style.id='rc230-kids-assets-style';style.textContent=`
  .r197-acc:has(.rc230-kids-asset) .r197-acc-art{min-height:190px!important;height:190px!important;overflow:visible!important;display:flex!important;align-items:center!important;justify-content:center!important;}
  .r197-acc-art .rc230-kids-asset{width:100%!important;height:100%!important;display:flex!important;align-items:center!important;justify-content:center!important;overflow:visible!important;background:transparent!important;}
  .r197-acc-art .rc230-kids-asset img{display:block!important;width:100%!important;height:176px!important;max-width:100%!important;max-height:176px!important;object-fit:contain!important;object-position:center!important;transform:none!important;filter:none!important;}
  .r197-acc-art .rc230-fox-asset img{height:178px!important;max-height:178px!important;}
  .r197-acc-art .rc230-owl-asset img{height:178px!important;max-height:178px!important;}
`;document.head.appendChild(style);
Object.values(ASSETS).forEach(src=>{const i=new Image();i.decoding='async';i.src=src;});
let raf=0;const schedule=()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;patch(document);});};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
window.addEventListener('pageshow',schedule);
window.addEventListener('hashchange',()=>setTimeout(schedule,25));
document.addEventListener('click',e=>{if(e.target.closest('[data-rc209variant],[data-r152pet],#rc208PetSel,#rc208CollectionSel'))setTimeout(schedule,25);},true);
new MutationObserver(schedule).observe(document.getElementById('app')||document.body,{childList:true,subtree:true});
})();
